// Construye rango startDate/endDate (UTC ms) para el día solicitado
const body = $input.first().json.body ?? $input.first().json;
const fecha = body.fecha; // 'YYYY-MM-DD'
const tz = body.timezone || 'America/Mexico_City';
const servicioSlug = body.servicio_slug;

const start = new Date(`${fecha}T00:00:00${tzOffset(tz)}`).getTime();
const end = new Date(`${fecha}T23:59:59${tzOffset(tz)}`).getTime();

function tzOffset() { return '-06:00'; }

return [{
  json: {
    fecha,
    servicio_slug: servicioSlug,
    timezone: tz,
    start_ms: start,
    end_ms: end
  }
}];

// Filtra y normaliza slots a HH:mm en zona local del consultorio
const raw = $input.first().json;
const tz = $('Preparar Rango').first().json.timezone;
const fecha = $('Preparar Rango').first().json.fecha;

const slotsEntrada = raw[Object.keys(raw)[0]]?.slots ?? raw.slots ?? [];

const toLocal = (iso) => new Intl.DateTimeFormat('es-MX', {
  hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz
}).format(new Date(iso));

const out = slotsEntrada.map(s => ({
  start: `${fecha}T${toLocal(s)}:00`,
  end: `${fecha}T${toLocal(s)}:00`
}));

return [{ json: { slots: out } }];
